import{esc,button as b,input,range,select}from'../phase4/ui.js';
import{cn,amount}from'./b06-model.js';
const n=(key,label,value,attrs='')=>`<label class="field">${label}<input type="number" min="-1000000" max="1000000" step="1" data-xfield="${key}" aria-label="${label}" value="${value??''}" ${attrs}></label>`;
const group=s=>`<div class="x-fields">${s}</div>`;
const dot=(i,act,selected=false,label='',attrs='')=>b(act,label||'●',`data-index="${i}" class="b6-dot ${selected?'selected':''}" aria-label="${esc(label||`第 ${i+1} 颗`)}" aria-pressed="${selected}" ${attrs}`);
const dots=n=>`<span class="b6-static-dots">${Array.from({length:n},()=>'<i></i>').join('')}</span>`;
const units=(h,t,o)=>`<div class="b6-units">${Array.from({length:h},()=>'<span class="b6-hundred">100</span>').join('')}${Array.from({length:t},()=>`<span class="b6-ten">${dots(10)}</span>`).join('')}${dots(o)}</div>`;
const why=(m,mode)=>select('why','你发现了什么',m.why,mode==='same'?[['same','只换位置，没有增加或拿走'],['long','摆得长，所以变多了']]:mode==='start'?[['start','没有从一开始，序号与总数不对应'],['last','最后喊几就一定有几个']]:mode==='twice'?[['twice','同一颗拿到了两个序号'],['shape','只是排列不够整齐']]:mode==='ones'?[['ones','每次十个，个位保持不变'],['all','每个数字都加十']]:[['carry','跨过数位边界时，更高位也会变化'],['one','只能改变一个数字']]);
const line=(min,max,marks)=>{const span=Math.max(1,max-min);return`<svg class="b6-line" viewBox="0 0 700 110" role="img" aria-label="${min} 到 ${max} 的数轴"><path d="M30 65H670" stroke="currentColor" stroke-width="2"/>${Array.from({length:11},(_,i)=>{const v=min+span*i/10;return`<path d="M${30+64*i} 60v10" stroke="currentColor"/><text x="${30+64*i}" y="95" text-anchor="middle">${Number.isInteger(v)?v:''}</text>`;}).join('')}${marks.map((p,i)=>`<circle cx="${30+640*(p.value-min)/span}" cy="${p.row?48:65}" r="7" fill="${p.color||'#b56a39'}"/><text x="${30+640*(p.value-min)/span}" y="${p.row?25:44}" text-anchor="middle">${esc(p.label??p.value)}</text>`).join('')}</svg>`;};
export function visual(t,m){switch(t.type){
case'x-counttrail':{const taps=m.moved&&t.recount?m.again:m.taps;return`${t.error?`<div class="b6-error-trail">小木偶的记录：${t.error.map((x,i)=>`<span>${i+1} → 珠 ${String.fromCharCode(65+x)}</span>`).join('')}</div>`:''}${t.crooked?'<p>小木偶的序号：3 → 4 → 5 → 6 → 7</p>':''}<div class="b6-beads ${m.moved?'scatter':t.layout}">${Array.from({length:t.n},(_,i)=>dot(i,'count-tap',taps.includes(i),`${t.error?String.fromCharCode(65+i):'●'}${taps.includes(i)?' · '+taps.map((x,j)=>x===i?j+1:null).filter(Boolean).join(','):''}`,m.moved&&!t.recount?'disabled':'')).join('')}</div><p class="quiet">${taps.length} 次标记${m.moved?' · 位置已换过':''}${m.before!==null?` · 第一次记录 ${m.before}`:''}</p>`;}
case'x-paircounts':return`<div class="b6-pairs"><div class="b6-pair-row ${t.spread?'spread':''}"><b>①</b>${Array.from({length:t.a},(_,i)=>dot(i,'pair-a',m.pairs.some(p=>p[0]===i)||m.pending===i,m.pairs.some(p=>p[0]===i)?String(m.pairs.findIndex(p=>p[0]===i)+1):'●',m.pairs.some(p=>p[0]===i)?'disabled':'')).join('')}</div><div class="b6-pair-row"><b>②</b>${Array.from({length:t.b},(_,i)=>dot(i,'pair-b',m.pairs.some(p=>p[1]===i),m.pairs.some(p=>p[1]===i)?String(m.pairs.findIndex(p=>p[1]===i)+1):'●',m.pairs.some(p=>p[1]===i)?'disabled':'')).join('')}</div>${t.c?`<div class="b6-pair-row"><b>③</b>${dots(t.c)}</div>`:''}</div><p>相同序号是一对。${m.pending===null?'先点第一排，再找第二排的伙伴。':'已选第一排，现在点第二排。'}</p>`;
case'x-onechange':return`<div class="b6-tray">${dots(t.n+(m.changed?t.delta:0))}</div>${m.changed?`<p>原来的猜测：${m.committed} · ${t.delta>0?'放进':'拿走'}了一颗</p>`:'<p class="quiet">先留下猜测，再改变数量。</p>'}`;
case'x-numberfaces':return`${t.fromLine?line(0,20,[{value:t.n,label:'这里'}]):''}<div class="b6-two"><div><p>选进小盘</p><div class="b6-pool">${Array.from({length:t.pool},(_,i)=>dot(i,'face-take',m.selected.includes(i))).join('')}</div></div>${!t.give?`<div><p>点格子画出同样多</p><div class="b6-frame">${Array.from({length:20},(_,i)=>b('face-dot',m.dots.includes(i)?'●':'',`data-index="${i}" class="b6-slot" aria-label="点图第 ${i+1} 格" aria-pressed="${m.dots.includes(i)}"`)).join('')}</div></div>`:''}</div>${!t.give?line(0,20,[{value:m.mark}]):''}`;
case'x-flashcount':return`<div class="b6-flash ${t.layout}" aria-live="polite">${m.open?(t.layout==='frame'?`<div class="b6-ten-frame">${Array.from({length:10},(_,i)=>`<span>${i<t.parts[0]||i>=5&&i<5+t.parts[1]?'●':''}</span>`).join('')}</div>`:t.parts?`<div>${dots(t.parts[0])}</div><div>${dots(t.parts[1])}</div>`:dots(t.n)):'<span>已盖住</span>'}</div><p class="quiet">${m.reveals?`看过 ${m.reveals} 次`:'准备好后再打开'}${t.parts?' · 分别记两部分和总数':''}</p>`;
case'x-fingers':return`<div class="b6-hand ${m.shown?'shown':''}">${['拇指','食指','中指','无名指','小指'].map((s,i)=>b('finger-toggle',s,`data-index="${i}" class="b6-finger" aria-pressed="${m.selected.includes(i)}"`)).join('')}</div><p>${m.shown?'选中的手指一起亮出来了。':'选好后一起亮出来。'}</p>`;
case'x-partbuild':return`<div class="b6-parts"><div>${dots(m.red)}</div><div>${dots(m.blue)}</div></div><p>留下的分法：${m.saved.map(p=>p.join(' ＋ ')).join('；')||'还没有'}</p>`;
case'x-bundlecount':{const used=m.groups.flat();return`<div class="b6-bundles">${m.groups.map((g,i)=>`<span class="b6-bundle" aria-label="第 ${i+1} 组，${g.length} 个">${dots(g.length)}</span>`).join('')}</div><div class="b6-pool dense">${Array.from({length:t.n},(_,i)=>used.includes(i)?'':dot(i,'bundle-pick',m.selected.includes(i))).join('')}</div><p>已选 ${m.selected.length} 个 · 每组 ${t.size} 个</p>`;}
case'x-countboard':return`<div class="b6-board">${Array.from({length:t.max},(_,i)=>{const k=t.holes.indexOf(i+1);return k<0?`<span>${i+1}</span>`:`<label><span class="sr-only">第 ${Math.floor(i/10)+1} 排末尾</span><input type="number" min="0" max="100" data-xfield="values.${k}" aria-label="第 ${Math.floor(i/10)+1} 排末尾" value="${m.values[k]??''}"></label>`;}).join('')}</div>`;
case'x-countwalk':{const path=[t.start,...m.hops],end=t.start+t.step*t.count,low=Math.min(t.start,end,...m.hops),high=Math.max(t.start,end,...m.hops),last=path.at(-1);return`<div class="b6-walk"><span>${t.infer?'自己找步长':`每步 ${t.step>0?'＋':''}${t.step}`}</span><strong>${last.toLocaleString('zh-CN')}</strong><small>走了 ${m.hops.length} / ${t.count} 步</small></div>${line(low,high,[{value:last,label:'现在'}])}<div class="b6-stations">${path.slice(-6).map((x,i)=>`<span>${x}</span>`).join('<i>→</i>')}</div>${path.length>6?`<details><summary>前面走过的站</summary><p>${path.join(' → ')}</p></details>`:''}`;}
case'x-digitcompare':return`<div class="b6-cards"><strong>${t.a}</strong><span>与</span><strong>${t.b}</strong></div>${line(0,10,[{value:m.a,label:`卡片 ${t.a}`,color:'#b56a39'},{value:m.b,label:`卡片 ${t.b}`,row:1,color:'#267c84'}])}`;
case'x-orderline':return`<div class="b6-cards">${t.values.map((v,i)=>b('order-pick',String(v),`data-index="${i}" aria-pressed="${m.order.includes(i)}"`)).join('')}</div><div class="b6-stations">${m.order.map(i=>`<span>${t.values[i]}</span>`).join('<i>→</i>')||'<span>排好的队伍放在这里</span>'}</div>${line(0,20,m.order.map(i=>({value:t.values[i]})))}`;
case'x-teenbuild':return`${m.bundle.length?units(0,1,0):''}<div class="b6-pool">${Array.from({length:t.n},(_,i)=>m.bundle.includes(i)?'':dot(i,'teen-pick',m.selected.includes(i))).join('')}</div><p>选了 ${m.selected.length} 颗${m.unpacked?' · 已拆开检查过':''}${m.rebundled?' · 已重新扎好':''}</p>${m.bundle.length?`<p class="b6-equation">10 ＋ ${m.ones??'？'} ＝ ${m.total??'？'}</p>`:''}`;
case'x-numberwrite':return`${t.mode==='objects'?`<div class="b6-tray">${t.n?dots(t.n):'空盘'}</div>`:t.mode==='word'||m.textHelp?`<div class="b6-number-label">${cn(t.n)}</div>`:t.mode==='symbol'||t.mode==='label'?`<div class="b6-number-label">${t.n}</div>`:`<p class="b6-audio-status">${m.heard?'听过了，可以再听':'点播放，听这个数'}</p>`}<div class="b6-tray">${amount(m)?units(m.hundreds,m.tens,m.ones):'把数量摆到这里'}</div>`;
default:return'';}}
export function controls(t,m){switch(t.type){
case'x-counttrail':return`${t.error?n('badStep','小木偶第几步重复了',m.badStep):''}<div class="choice-line">${b('count-undo','撤回一次')}${b('count-reset','重新数')}</div>${n('total','第一次的总数',m.total,m.moved?'disabled':'')}${t.rearrange?`${n('prediction','挪动后会有几个',m.prediction,m.moved?'disabled':'')}${b('count-move','把位置打散',m.moved?'disabled':'')}${n('after','换位置后有几个',m.after)}`:''}${t.error||t.crooked||t.rearrange?why(m,t.error?'twice':t.crooked?'start':'same'):''}`;
case'x-paircounts':return`${b('pair-undo','撤回一对')}${group(n('a','第一组有几个',m.a)+n('b','第二组有几个',m.b)+select('relation','第一组比第二组',m.relation,[['more','多'],['fewer','少'],['equal','一样多']]))}${t.c?group(select('most','最多的一组',m.most,[['0','①'],['1','②'],['2','③']])+select('least','最少的一组',m.least,[['0','①'],['1','②'],['2','③']])):''}`;
case'x-onechange':return`${n('guess','先猜会有几个',m.guess,m.changed?'disabled':'')}${b('one-change',t.delta>0?'放入一颗':'拿走一颗',m.changed?'disabled':'')}${group(n('total','现在的总数',m.total)+select('why','它是原来数量的',m.why,[['next','后一个数'],['previous','前一个数'],['same','同一个数']]))}`;
case'x-numberfaces':return`${!t.give?range('mark','把点放到数轴上',m.mark,0,20):''}${n('numeral','写成数字',m.numeral)}${t.neighbors?group(n('before','前一个数',m.before)+n('after','后一个数',m.after)):''}`;
case'x-flashcount':return`<button type="button" data-b6="peek" ${m.open?'disabled':''}>${m.reveals?'再看一秒':'看一秒'}</button>${group((t.parts?n('a',t.layout==='frame'?'上排':'左半',m.a,m.open?'disabled':'')+n('b',t.layout==='frame'?'下排':'右半',m.b,m.open?'disabled':''):'')+n('answer','一共有几个',m.answer,m.open?'disabled':''))}`;
case'x-fingers':return`${b('finger-show','一起亮出')}${n('total','表示几个',m.total)}`;
case'x-partbuild':return`${group(range('red','橙色几个',m.red,0,10)+range('blue','蓝色几个',m.blue,0,10))}${b('parts-save','留下这个分法')}${n('total','合起来几个',m.total)}`;
case'x-bundlecount':return`<div class="choice-line">${b('bundle-wrap','把选好的扎成一组')}${b('bundle-repeat',`照着再分一组 ${t.size} 个`)}${b('bundle-reset','全部拆开')}</div>${group(n('groupsCount','完整的组有几组',m.groupsCount)+n('remainder','零散的有几个',m.remainder)+n('total','物品一共有几个',m.total))}${t.reason?select('why','组数为什么不等于物品数',m.why,[['units','每组里有十个，要换回物品的个数'],['same','一组就当一个物品']]):''}`;
case'x-countboard':return'<p class="quiet">填完十个空格。想练口头数数时，可以从任意一个数开始。</p>';
case'x-countwalk':return`${t.infer?n('step','每次改变多少（往回用负数）',m.step):''}${n('next','下一站',m.next)}<div class="choice-line">${b('walk-hop','走到这一站',m.hops.length===t.count?'disabled':'')}${b('walk-undo','退回上一步')}${b('walk-reset','回到起点')}</div>${t.reason?why(m,t.reason):''}`;
case'x-digitcompare':return`${group(range('a',`卡片 ${t.a} 的位置`,m.a,0,10)+range('b',`卡片 ${t.b} 的位置`,m.b,0,10))}${select('relation',`${t.a} 与 ${t.b} 的关系`,m.relation,[['less','＜'],['greater','＞'],['equal','＝']])}`;
case'x-orderline':return'<p class="quiet">点已经排好的卡片可以拿回，再换个位置排。</p>';
case'x-teenbuild':return`<div class="choice-line">${b('teen-wrap','十颗扎成一束')}${b('teen-unpack','拆开这一束')}</div>${group(n('tens','几个十',m.tens)+n('ones','还剩几个一',m.ones)+n('total','一共几个',m.total))}${select('why','十位上的 1 代表',m.why,[['ten','十个一'],['one','只有一个物品']])}`;
case'x-numberwrite':return`${t.mode==='audio'?'<div class="choice-line"><button type="button" data-b6="hear">▶ 播放这个数</button><button type="button" data-b6="text">看文字提示</button><span id="b6-audio-message" role="status"></span></div>':''}<div class="b6-unit-controls">${[['hundreds','百'],['tens','十'],['ones','一']].map(([k,l])=>`<div>${b('write-add',`＋ 一个${l}`,`data-unit="${k}" data-delta="1"`)}${b('write-add',`− 一个${l}`,`data-unit="${k}" data-delta="-1"`)}</div>`).join('')}${b('write-exchange','十个一换成十／十个十换成百')}</div>${group(input('numeral','写成数字',m.numeral,'inputmode="numeric"')+input('word','中文名字',m.word))}${t.ink?`<details class="b6-writing"><summary>也写一写（只保存笔迹，不判字）</summary><svg id="b6-ink" viewBox="0 0 600 180" role="img" aria-label="手写区，可用鼠标或触控笔书写"><path class="b6-paper" d="M0 90H600M150 0V180M300 0V180M450 0V180"/>${m.ink.map(s=>`<polyline points="${s.map(p=>`${p[0]*600},${p[1]*180}`).join(' ')}"/>`).join('')}</svg>${b('write-clear-ink','清空笔迹')}<p class="quiet">输入框用于核对数值，笔迹留给之后回看。</p></details>`:''}`;
default:return'';}}
export const render=(t,m)=>`<div class="b6-lab"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div></div>`;
